<script setup lang="ts">
import {acquireInert} from "../services/inertLease"
import { computed,nextTick,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { useAccountEditor } from '../composables/useAccountEditor'
import AccountAvatar from './AccountAvatar.vue'
import AccountPasswordInput from './AccountPasswordInput.vue'
const props=defineProps<{section?:'profile'|'security';flat?:boolean}>()
const { auth, form, saved, username, usernamePassword, passwords, loading, loaded, busy, message, tone, avatarPath, avatarPreview, profileDirty, profileError, usernameError, passwordError, passwordChecks, passwordStrength, load, saveProfile, discardProfile, selectAvatar, clearAvatar, rename, changePassword } = useAccountEditor()
const editing=ref(''),credential=ref('')
const modalOpen=computed(()=>Boolean(editing.value||credential.value)),modal=ref<HTMLElement|null>(null)
const modalTitle=computed(()=>credential.value==='username'?'修改用户名':credential.value==='password'?'修改密码':editing.value==='avatar'?'更换头像':`修改${fieldLabels[editing.value as keyof typeof fieldLabels]||''}`)
const profileFields=['nickName','email','phonenumber'] as const
const fieldLabels={nickName:'昵称',email:'邮箱',phonenumber:'手机号码'}
async function beginEdit(field: string){if(!await requestLeave())return;discardProfile();editing.value=field;await nextTick();document.querySelector<HTMLInputElement>('.account-field input')?.focus()}
function cancelEdit(){if(busy.value)return;discardProfile();username.value=saved.value.userName;clearCredentials();editing.value='';credential.value=''}
async function submitProfile(){await saveProfile();if(tone.value==='success'&&!profileDirty.value)editing.value=''}
async function submitUsername(){await rename();if(tone.value==='success')credential.value=''}
async function submitPassword(){await changePassword();if(tone.value==='success')credential.value=''}
async function copyUsername(){try{await navigator.clipboard.writeText(saved.value.userName);tone.value='success';message.value='用户名已复制'}catch{tone.value='error';message.value='复制失败，请手动复制用户名'}}
function clearCredentials(){usernamePassword.value='';Object.assign(passwords,{oldPassword:'',newPassword:'',confirmation:''})}
onMounted(load)
import { confirmDialog,productDialogState } from '../services/productDialog'
async function requestLeave(){if(busy.value)return false;if(!profileDirty.value && username.value===saved.value.userName && !usernamePassword.value && !passwords.oldPassword && !passwords.newPassword && !passwords.confirmation)return true;return confirmDialog({title:'放弃未保存的资料？',message:'资料或登录凭据有尚未保存的修改。',confirmText:'放弃修改',cancelText:'继续编辑'})}
defineExpose({requestLeave})
const mode=ref(props.section==='security'?'security':'profile')
async function openMode(value: string){if(!await requestLeave())return;discardProfile();editing.value='';username.value=saved.value.userName;clearCredentials();if(value==='username'||value==='password')credential.value=value;else{credential.value='';mode.value=value}message.value=''}
let origin:HTMLElement|null=null,root:HTMLElement|null=null,savedOverflow='',releaseInert=()=>{},locked=false
function unlock(){if(!locked)return;locked=false;document.body.style.overflow=savedOverflow;releaseInert();root=null;document.removeEventListener('keydown',modalKeydown,true);if(origin?.isConnected)origin.focus({preventScroll:true});origin=null}
function modalKeydown(event:KeyboardEvent){if(!modalOpen.value||productDialogState.open)return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();cancelEdit();return}if(event.key!=='Tab'||!modal.value)return;const items=[...modal.value.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),[tabindex="0"]')].filter(node=>node.getClientRects().length),first=items[0],last=items.at(-1);if(!first){event.preventDefault();modal.value.focus()}else if(!modal.value.contains(document.activeElement)||document.activeElement===modal.value){event.preventDefault();(event.shiftKey?last:first)?.focus()}else if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
watch(modalOpen,async open=>{if(!open){unlock();return}origin=document.activeElement instanceof HTMLElement?document.activeElement:null;savedOverflow=document.body.style.overflow;root=document.querySelector<HTMLElement>('#app');releaseInert=acquireInert(root);document.body.style.overflow='hidden';locked=true;document.addEventListener('keydown',modalKeydown,true);await nextTick();if(modalOpen.value)(modal.value?.querySelector<HTMLInputElement>('input:not([type=file])')||modal.value)?.focus()})
onBeforeUnmount(unlock)
</script>
<template>
<div class="account-manager" :class="{'account-flat':flat}">
  <div v-if="loading" class="account-state" role="status"><span class="account-spinner"/><strong>正在读取账号信息</strong><p>稍等，个人资料马上就绪</p></div>
  <div v-else-if="!loaded" class="account-state"><span class="account-state-icon">◌</span><strong>{{ auth.token ? '暂时无法读取账号' : '当前为离线状态' }}</strong><p>{{ message || '连接服务器后即可编辑资料和管理账号安全' }}</p><button v-if="auth.token" type="button" class="account-primary" @click="load">重新加载</button></div>
  <template v-else>
    <nav v-if="!section" class="account-tabs" aria-label="账号设置"><button :aria-pressed="mode === 'profile'" @click="openMode('profile')">个人资料</button><button :aria-pressed="mode !== 'profile'" @click="openMode('security')">账号安全</button></nav>
    <div v-if="message&&!modalOpen" class="account-feedback" :data-tone="tone" role="status" aria-live="polite"><span>{{ tone === 'success' ? '✓' : tone === 'error' ? '!' : 'i' }}</span>{{ message }}</div>
    <section v-if="mode === 'profile'" class="account-card">
      <div class="account-avatar-editor"><AccountAvatar :path="avatarPath" :name="saved.nickName || saved.userName" /><div class="account-identity-text"><strong>{{saved.nickName || saved.userName}}</strong><div class="account-username-line"><small>{{saved.userName}}</small><button type="button" class="account-copy" aria-label="复制用户名" title="复制用户名" @click="copyUsername"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/></svg></button></div></div><button type="button" class="account-avatar-change" :disabled="Boolean(busy)" @click="beginEdit('avatar')">更换头像</button></div>
      <p class="account-section-label">基本信息</p>
      <div v-for="field in profileFields" :key="field" class="account-readonly"><span>{{fieldLabels[field]}}</span><strong>{{field==='phonenumber' && saved[field] ? saved[field].replace(/^(...).*?(..)$/,'$1****$2') : saved[field] || '未设置'}}</strong><button type="button" :disabled="Boolean(busy)" @click="beginEdit(field)">修改 ›</button></div>
      <div class="account-readonly"><span>登录用户名</span><strong>{{saved.userName}}</strong><button type="button" @click="openMode('username')">修改 ›</button></div>

    </section>
    <section v-else-if="mode === 'security'" class="account-card">
      <header v-if="!flat" class="account-card-heading"><h2>登录安全</h2><p>管理登录密码</p></header>
      <button class="account-security-row" type="button" @click="openMode('password')"><span v-if="!flat" class="account-security-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/></svg></span><span><strong>登录密码</strong><small>定期更新，避免与其他账号使用相同密码</small></span><span>修改 ›</span></button>
      <div v-if="!flat" class="account-security-note">修改登录凭据不会改变你的笔记、附件或同步空间。</div>
    </section>
    <Teleport to="body">
      <div v-if="modalOpen" class="account-edit-overlay">
        <section ref="modal" class="account-edit-dialog" role="dialog" aria-modal="true" aria-labelledby="account-edit-title" tabindex="-1">
          <header class="account-edit-heading"><div><h2 id="account-edit-title">{{modalTitle}}</h2><p>{{credential==='password'?'验证当前密码后设置新密码。':credential==='username'?'修改后，下次登录使用新用户名。':'确认保存后生效。'}}</p></div><button type="button" aria-label="关闭编辑" :disabled="Boolean(busy)" @click="cancelEdit">×</button></header>
          <div v-if="message" class="account-feedback" :data-tone="tone" role="status" aria-live="polite">{{message}}</div>
      <form v-if="editing" @submit.prevent="submitProfile"><fieldset :disabled="Boolean(busy)">
        <template v-if="editing==='avatar'"><div class="account-avatar-preview"><AccountAvatar :path="avatarPath" :name="saved.nickName||saved.userName" :preview="avatarPreview"/></div><label class="account-upload">选择头像<input type="file" accept="image/png,image/jpeg" @change="selectAvatar"/></label><small>JPG 或 PNG，最多 5 MB；确认保存后生效</small></template>
        <label v-for="field in profileFields.filter(value=>value===editing)" :key="field" class="account-field"><span>{{fieldLabels[field]}}</span><input v-model.trim="form[field]" :type="field==='email'?'email':field==='phonenumber'?'tel':'text'" :maxlength="field==='email'?50:field==='nickName'?30:11" :required="field==='nickName'"/></label>
        <p v-if="profileDirty && profileError" class="account-field-error">{{profileError}}</p>
        <footer class="account-actions"><button type="button" class="account-secondary" @click="cancelEdit">取消</button><button type="submit" class="account-primary" :disabled="!profileDirty || Boolean(profileError)">{{busy==='profile'?'正在保存…':'保存'}}</button></footer>
      </fieldset></form>
          <template v-else-if="credential==='username'">
      <div class="account-info">当前用户名 <strong>{{ saved.userName }}</strong></div>
      <form @submit.prevent="submitUsername"><fieldset :disabled="Boolean(busy)">
        <label class="account-field"><span>新用户名</span><input v-model.trim="username" name="newUsername" required minlength="2" maxlength="20" autocomplete="username" placeholder="输入新的登录用户名"/><small class="account-hint">2–20 个字符，支持文字、数字、下划线、点和短横线</small><small v-if="username !== saved.userName && usernameError" class="account-field-error">{{ usernameError }}</small></label>
        <AccountPasswordInput v-model="usernamePassword" label="当前密码" name="renameCurrentPassword"/>
        <footer class="account-actions"><button type="button" class="account-secondary" :disabled="Boolean(busy)" @click="cancelEdit">取消</button><button type="submit" class="account-primary" :disabled="Boolean(usernameError) || !usernamePassword">{{ busy === 'username' ? '正在修改…' : '确认修改用户名' }}</button></footer>
      </fieldset></form>
          </template><template v-else>
      <form @submit.prevent="submitPassword"><fieldset :disabled="Boolean(busy)">
        <AccountPasswordInput v-model="passwords.oldPassword" label="当前密码" name="currentPassword"/>
        <AccountPasswordInput v-model="passwords.newPassword" label="新密码" name="newPassword" autocomplete="new-password"/>
        <div v-if="passwords.newPassword" class="account-strength"><div><i v-for="n in 3" :key="n" :class="{filled:n <= passwordStrength.score}" :data-score="passwordStrength.score"/></div><small>密码强度：{{ passwordStrength.label }}</small></div>
        <AccountPasswordInput v-model="passwords.confirmation" label="确认新密码" name="confirmPassword" autocomplete="new-password"/>
        <ul class="account-password-checks"><li :class="{met:passwordChecks.length}"><span>{{ passwordChecks.length ? '✓' : '○' }}</span>长度为 5–20 个字符</li><li :class="{met:passwordChecks.different}"><span>{{ passwordChecks.different ? '✓' : '○' }}</span>与当前密码不同</li><li :class="{met:passwordChecks.matches}"><span>{{ passwordChecks.matches ? '✓' : '○' }}</span>两次新密码输入一致</li></ul>
        <small v-if="passwords.confirmation && !passwordChecks.matches" class="account-field-error">两次输入的新密码不一致</small>
        <footer class="account-actions"><button type="button" class="account-secondary" :disabled="Boolean(busy)" @click="cancelEdit">取消</button><button type="submit" class="account-primary" :disabled="Boolean(passwordError)">{{ busy === 'password' ? '正在修改…' : '确认修改密码' }}</button></footer>
      </fieldset></form>
          </template>
        </section>
      </div>
    </Teleport>
  </template>
</div>
</template>
<style scoped>
