.account-edit-overlay{position:fixed;inset:0;z-index:900;display:grid;place-items:center;padding:24px;background:rgba(17,30,23,.38);backdrop-filter:blur(3px);color:var(--account-ink)}.account-edit-dialog{width:min(460px,100%);box-sizing:border-box;max-height:calc(100dvh - 48px);overflow-y:auto;overscroll-behavior:contain;background:var(--surface,#fff);border:1px solid var(--account-line);border-radius:16px;padding:24px;box-shadow:0 24px 72px #16352630;outline:none}.account-edit-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:22px}.account-edit-heading h2{margin:0 0 8px;font-size:19px}.account-edit-heading p{margin:0;color:var(--account-muted);font-size:13px;line-height:1.6}.account-edit-heading>button{border:0;background:transparent;color:var(--account-muted);width:32px;height:32px;font-size:23px;cursor:pointer;border-radius:8px}.account-edit-heading>button:hover{background:var(--account-subtle,#f4f7f4)}.account-avatar-preview{display:flex;justify-content:center;--account-avatar-size:96px;padding:8px 0 16px}.account-edit-dialog button:disabled{opacity:.55;cursor:default}.account-edit-dialog .account-actions{margin-top:6px}.account-edit-dialog fieldset:disabled{opacity:.7}@media(max-width:600px){.account-edit-overlay{padding:16px}.account-edit-dialog{padding:20px;max-height:calc(100dvh - 32px)}}
.account-manager.account-flat{margin:0;max-width:none}.account-flat .account-card{padding:0;border:0;border-radius:0;background:transparent}.account-flat .account-security-row{padding:20px 0;min-height:80px}.account-flat .account-security-row>span:first-child{flex:1;display:grid;gap:7px}.account-flat .account-security-row>span:last-child{flex:0;display:block;color:var(--account-primary);white-space:nowrap}.account-flat .account-state{padding:20px 0;border:0;border-radius:0}
